#READ ME

#YOU SHOULD ONLY BE USING THIS IF YOU HAVE THE
#Incidents_2014_2018_flood_xy.csv file!!!!!!
#IT CAN BE GENERATED BY RUNNING QUINN_EmergencyMapping


# ============================================================
# SANDIA CREEK BRIDGE EMERGENCY ACCESS STUDY AREA
# Rebuild map starting from Incidents_2014_2018_flood_xy
# ============================================================

# ------------------------------------------------------------
# 1. Load packages
# ------------------------------------------------------------

library(tidyverse)
library(sf)
library(osmdata)
library(tigris)

options(tigris_use_cache = TRUE)


# ------------------------------------------------------------
# 2. Define map extent
# ------------------------------------------------------------

# Geographic extent encompassing the incident area,
# NCFPD stations, Temecula, and Riverside/Perris candidate origin.

map_xlim <- c(-117.40, -117.14)
map_ylim <- c(33.25, 33.82)

study_bbox <- st_bbox(
  c(
    xmin = map_xlim[1],
    ymin = map_ylim[1],
    xmax = map_xlim[2],
    ymax = map_ylim[2]
  ),
  crs = st_crs(4326) #This is the coordinate reference system used (WGS 1984)
)

# Bounding box format required by osmdata
road_bbox <- c(
  map_xlim[1],
  map_ylim[1],
  map_xlim[2],
  map_ylim[2]
)
#road_bbox downloads OSM features with OSM data

# ------------------------------------------------------------
# 3. Prepare emergency incident locations
# ------------------------------------------------------------

#this code sets the longitude and latitude collumns to numeric
incidents_map <- Incidents_2014_2018_flood_xy %>%
  mutate(
    longitude = suppressWarnings(as.numeric(longitude)),
    latitude = suppressWarnings(as.numeric(latitude))
  ) %>%
  filter(
    is.finite(longitude),
    is.finite(latitude),
    between(longitude, map_xlim[1], map_xlim[2]),
    between(latitude, map_ylim[1], map_ylim[2])
  ) #this filter removes rows that do not have the coordinates

# Convert incidents to spatial points using the spatial records
# that were just filtered
incident_points_map <- st_as_sf(
  incidents_map,
  coords = c("longitude", "latitude"),
  crs = 4326,
  remove = FALSE
) 
#remove = FALSE keeps the original latitude/longitude instead of removing them
#after creating the spatial geometries

cat("Incident records mapped:", nrow(incident_points_map), "\n")
#this command reports how many incidents were able to be mapped.

# ------------------------------------------------------------
# 4. Download 2010 Census blocks and tracts
# ------------------------------------------------------------

# San Diego County = 073
# Riverside County = 065

county_codes <- c("073", "065")

# Download blocks
blocks_2010 <- purrr::map(
  county_codes,
  ~ tigris::blocks(
    state = "06",
    county = .x, #substitutes each county code
    year = 2010, #specifies which census block shapefiles collected
    class = "sf"
  )
) %>%
  do.call(rbind, .) #this combines both counties into one shapefile

# Download tracts #does the same thing as above, but for the census tracts
tracts_2010 <- purrr::map(
  county_codes,
  ~ tigris::tracts(
    state = "06",
    county = .x,
    year = 2010,
    class = "sf"
  )
) %>%
  do.call(rbind, .)

# Transform to longitude/latitude
blocks_2010 <- st_transform(blocks_2010, 4326) #locks in the coordinate system
tracts_2010 <- st_transform(tracts_2010, 4326) 

# Crop to map extent
#this retains the block and tract polygons intersecting with study area
blocks_in_extent <- st_crop(
  blocks_2010,
  study_bbox
) %>%
  mutate(
    block_geoid_tiger = as.character(GEOID10),
    tract_geoid_tiger = str_sub(block_geoid_tiger, 1, 11)
  )

tracts_in_extent <- st_crop(
  tracts_2010,
  study_bbox
) %>%
  mutate(
    tract_geoid_tiger = as.character(GEOID10)
  )

#GEOID10 is the tract identifier 
#str_sub(block_geoid_tiger, 1, 11) extracts the tract GEOID from each block GEOID
#this allows us to assign emergency incidents to tracts and blocks.

# ------------------------------------------------------------
# 5. Assign incidents to Census blocks and tracts
# ------------------------------------------------------------

#*this code performs a spacial join and connects the incidents to blocks and tracts
incidents_spatially_assigned <- st_join(
  incident_points_map,
  blocks_in_extent %>%
    select(
      block_geoid_tiger,
      tract_geoid_tiger
    ),
  join = st_within,
  left = TRUE
)

# Check incident assignment
#this codes lets us know how many incidents have a tract and block
# and how many do not 
#the drop geometry allows us to remove the spacial component to do summary statistic
incident_assignment_check <- incidents_spatially_assigned %>%
  st_drop_geometry() %>%
  summarise(
    total_incidents = n(),
    assigned_blocks = sum(!is.na(block_geoid_tiger)),
    unassigned_incidents = sum(is.na(block_geoid_tiger))
  )

print(incident_assignment_check)


# ------------------------------------------------------------
# 6. Create Census tract labels
# ------------------------------------------------------------

# Project before finding representative label points
tract_labels <- tracts_in_extent %>%
  st_transform(26911) %>% #transforms polygon measurements to meters
  st_point_on_surface() %>% #creates a representative point for each tract
  st_transform(4326) # this transforms it back into a shapefile later used by:
#geom_sf_text(
#  data = tract_labels,
#  aes(label = tract_geoid_tiger))

#it creates the labels for the tracts

# ------------------------------------------------------------
# 7. Retrieve OpenStreetMap roads
# ------------------------------------------------------------

osm_roads_raw <- osmdata::opq( #this creates a queary for the geographic area
  bbox = road_bbox,
  timeout = 180
) %>%
  osmdata::add_osm_feature( #requests osm highway features
    key = "highway"
  ) %>%
  osmdata::osmdata_sf( #converts the downloaded items as spacial features
    quiet = FALSE
  )

osm_roads <- osm_roads_raw$osm_lines #extracts road line geometries 

#these are conditionals to stop the code if there is nothing returned for our roads of interest
if (is.null(osm_roads) || nrow(osm_roads) == 0) {
  stop("No OSM road geometries were returned.")
}

# Ensure a road-name field exists
if (!"name" %in% names(osm_roads)) {
  osm_roads$name <- NA_character_
}

# Extract the three requested roads
named_roads_map <- osm_roads %>%
  filter(!is.na(name)) %>%
  mutate(
    road_name = case_when(
      str_detect(
        name,
        regex("^De Luz( Road| Rd\\.?|$)", ignore_case = TRUE)
      ) ~ "De Luz Road",
      
      str_detect(
        name,
        regex("^Sandia Creek( Drive| Dr\\.?|$)", ignore_case = TRUE)
      ) ~ "Sandia Creek Drive",
      
      str_detect(
        name,
        regex("^Rock Mountain( Drive| Dr\\.?|$)", ignore_case = TRUE)
      ) ~ "Rock Mountain Drive",
      
      TRUE ~ NA_character_
    )
  ) %>%
  filter(!is.na(road_name)) %>%
  st_transform(4326)

# Check which roads were retrieved
named_roads_map %>%
  st_drop_geometry() %>%
  distinct(name, road_name) %>%
  arrange(road_name) %>%
  print(n = Inf)


# ------------------------------------------------------------
# 8. Retrieve Santa Margarita River
# ------------------------------------------------------------

river_query <- osmdata::opq(
  bbox = road_bbox,
  timeout = 180
) %>%
  osmdata::add_osm_feature(
    key = "waterway",
    value = "river"
  )

river_data <- osmdata::osmdata_sf(
  river_query,
  quiet = FALSE
)

osm_santa_margarita <- river_data$osm_lines

if (is.null(osm_santa_margarita) ||
    nrow(osm_santa_margarita) == 0) {
  stop("No OSM river geometries were returned.")
}

if (!"name" %in% names(osm_santa_margarita)) {
  osm_santa_margarita$name <- NA_character_
}

osm_santa_margarita <- osm_santa_margarita %>%
  filter(
    str_detect(
      coalesce(name, ""), #Replaces missing names with empty strings
      regex("Santa Margarita", ignore_case = TRUE) #search is case-insensitive 
    )
  ) %>%
  st_transform(4326)


# ------------------------------------------------------------
# 9. Prepare all seven candidate response locations
# ------------------------------------------------------------
#The frist part of the mutate contains all of the relevant firestations
#this converts coordinates to a numerical value so they can be used for 
#spacial conversion
all_site_points_plot <- all_sites %>%
  mutate(
    origin_lon = as.numeric(origin_lon),
    origin_lat = as.numeric(origin_lat),
    
    #makes readable lables for the map
    site_label = case_when(
      !is.na(station_no) ~ paste0("NCFPD ", station_no), 
      
      source == "Riverside" ~ "CAL FIRE RRU HQ",
      
      TRUE ~ "Temecula Civic Center"
    )
  ) %>%
  filter(
    is.finite(origin_lon),
    is.finite(origin_lat)
  ) %>%
  #this converts the station locations into spatial points
  st_as_sf(
    coords = c("origin_lon", "origin_lat"),
    crs = 4326,
    remove = FALSE
  )

# Confirm all seven points are present
print(
  all_site_points_plot %>%
    st_drop_geometry() %>%
    select(origin_name, site_label, origin_lat, origin_lon),
  n = Inf
)


# ------------------------------------------------------------
# 10. Create historical crossing point
# ------------------------------------------------------------

#waypoint for the bridge 
old_crossing <- st_as_sf(
  tibble(
    crossing_name = "Original Sandia Creek low-flow crossing",
    longitude = -117.2416111,
    latitude = 33.4140861
  ),
  coords = c("longitude", "latitude"),
  crs = 4326
)


# ------------------------------------------------------------
# 11. Define map colors
# ------------------------------------------------------------

map_colors <- c(
  
  # Roads
  "De Luz Road" = "#D89000",
  "Sandia Creek Drive" = "#D95BEF",
  "Rock Mountain Drive" = "#8C85FF",
  
  # NCFPD stations
  "NCFPD Station 1" = "#A0A000",
  "NCFPD Station 2" = "#50B500",
  "NCFPD Station 3" = "#00B58A",
  "NCFPD Station 4" = "#00BFC4",
  "NCFPD Station 5" = "#00A6E6",
  
  # Other candidate response origins
  "CAL FIRE Riverside Unit Headquarters" = "#F8766D",
  "Temecula Civic Center" = "#E84FBF"
)


# ------------------------------------------------------------
# 12. Generate final map
# ------------------------------------------------------------

sandia_emergency_map <- ggplot() +
  
  # Census blocks
  geom_sf(
    data = blocks_in_extent,
    fill = "grey96",
    color = "purple",
    linewidth = 0.15
  ) +
  
  # Census tract boundaries
  geom_sf(
    data = tracts_in_extent,
    fill = NA,
    color = "black",
    linewidth = 0.65
  ) +
  
  # Santa Margarita River
  geom_sf(
    data = osm_santa_margarita,
    color = "deepskyblue3",
    linewidth = 1.3
  ) +
  
  # Named roads
  geom_sf(
    data = named_roads_map,
    aes(color = road_name),
    linewidth = 1.2
  ) +
  
  # Census tract labels
  geom_sf_text(
    data = tract_labels,
    aes(label = tract_geoid_tiger),
    size = 2.5,
    color = "black"
  ) +
  
  # Emergency incidents
  geom_sf(
    data = incidents_spatially_assigned,
    color = "firebrick",
    size = 0.8,
    alpha = 0.65
  ) +
  
  # All seven candidate response locations
  geom_sf(
    data = all_site_points_plot,
    aes(color = origin_name),
    shape = 8,
    size = 5,
    stroke = 1.5
  ) +
  
  # Candidate response location labels
  geom_sf_text(
    data = all_site_points_plot,
    aes(label = site_label),
    color = "black",
    size = 2.8,
    nudge_y = 0.006,
    check_overlap = TRUE,
    show.legend = FALSE
  ) +
  
  # Historical crossing
  geom_sf(
    data = old_crossing,
    color = "blue",
    shape = 17,
    size = 4
  ) +
  
  # Geographic coordinate system
  coord_sf(
    crs = st_crs(4326),
    default_crs = st_crs(4326),
    xlim = map_xlim,
    ylim = map_ylim,
    expand = FALSE
  ) +
  
  # Shared road/station legend
  scale_color_manual(
    values = map_colors,
    name = "Road / Candidate Response Origin",
    drop = FALSE
  ) +
  
  labs(
    title = "Sandia Creek Bridge Emergency Access Study Area",
    subtitle = paste(
      "2010 Census blocks, tracts, emergency incidents,",
      "major roads, waterways, and candidate response origins"
    ),
    x = "Longitude",
    y = "Latitude",
    caption = paste(
      "Blue triangle = Historical Sandia Creek crossing.",
      "Stars = Candidate response origins; actual apparatus origins",
      "have not been independently verified."
    )
  ) +
  
  theme_bw() +
  
  theme(
    plot.title = element_text(
      face = "bold",
      size = 14
    ),
    panel.grid = element_line(
      color = "grey90"
    ),
    legend.position = "right"
  )


# Display map
print(sandia_emergency_map)


# ------------------------------------------------------------
# 13. Save map
# ------------------------------------------------------------

ggsave(
  filename = "Sandia_Creek_Emergency_Access_Map.png",
  plot = sandia_emergency_map,
  width = 16,
  height = 12,
  units = "in",
  dpi = 300
)